 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; pub fn process_ecosystem (verbose : bool , dry_run : bool , base_path : & Path , recursive : bool , global_config : & SplitDeclsConfig ,) -> Result < () > { if verbose { if dry_run { println ! ("*** Running in DRY-RUN mode. No files will be modified. ***") ; } println ! ("Processing ecosystem at: {}" , base_path . display ()) ; println ! ("Recursive: {}" , recursive) ; } let mut processed_count = 0 ; if recursive { for entry in WalkDir :: new (base_path) . into_iter () . filter_map (| e | e . ok ()) { if entry . file_name () == "Cargo.toml" { let cargo_toml_path = entry . path () ; let crate_path = cargo_toml_path . parent () . context ("Cargo.toml has no parent directory") ? ; if should_process_crate (crate_path , verbose) ? { if verbose { println ! ("Processing crate: {}" , crate_path . display ()) ; } simple_process_crate (crate_path , global_config , dry_run) ? ; processed_count += 1 ; } } } } else { let cargo_toml = base_path . join ("Cargo.toml") ; if cargo_toml . exists () { if should_process_crate (base_path , verbose) ? { if verbose { println ! ("Processing crate: {}" , base_path . display ()) ; } simple_process_crate (base_path , global_config , dry_run) ? ; processed_count += 1 ; } } else { println ! ("No Cargo.toml found at {}" , base_path . display ()) ; } } if verbose { println ! ("Processed {} crates" , processed_count) ; } Ok (()) }